// Revenue conversion fix: ensure paidEvents increments on successful checkout
// This module hooks into the checkout completion flow and triggers revenue recording

const revenueModule = require('./revenue-module');

module.exports = function attachConversionHook(app) {
  app.post('/api/checkout/complete', async (req, res, next) => {
    const originalJson = res.json.bind(res);
    res.json = async function (body) {
      if (body && body.success) {
        try {
          await revenueModule.recordEvent({
            type: 'paid',
            amount: req.body.amount || 0,
            currency: req.body.currency || 'USD',
            timestamp: new Date().toISOString()
          });
        } catch (err) {
          console.error('Revenue conversion hook error:', err);
        }
      }
      return originalJson(body);
    };
    next();
  });
};
